input.command:
mkdir -p /tmp/hzt-2734055227/bench-run-mmqxi2c8/ops && cat > /tmp/hzt-2734055227/bench-run-mmqxi2c8/ops/watch.sh <<'EOF'
#!/bin/bash
cd /tmp/hzt-2734055227/bench-run-mmqxi2c8/clone
R=$HARNESS_REPO
while true; do
  st=$(gh issue view 1 -R $R --json state -q .state 2>/dev/null)
  [ "$st" = CLOSED ] && { echo "PRD closed"; break; }
  [ "$(gh issue list -R $R --state open --json number -q length 2>/dev/null)" = 0 ] && { echo "no open issues"; break; }
  gh issue list -R $R --label agent-blocked --json number -q '.[].number' 2>/dev/null | grep -q . && { echo "agent-blocked present"; break; }
  harness status 2>&1 | grep -qE "DOWN|STUCK|PAUSED" && { echo "fleet DOWN/STUCK/PAUSED"; break; }
  sleep 90
done
harness status 2>&1 | tail -15; gh issue list -R $R --state all; gh pr list -R $R --state all
EOF
chmod +x /tmp/hzt-2734055227/bench-run-mmqxi2c8/ops/watch.sh

